:root {
  --bg: #f4f1de;
  --card-bg: #ffffff;
  --text: #2d2a32;
  --accent: #e07a5f;
  --accent-dark: #c45a3e;
  --border: #d9d1c7;
  --focus: #3d5a80;
  --radius: 12px;
  --shadow: 0 4px 12px rgba(0, 0, 0, 0.08);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2rem;
  width: 100%;
  max-width: 500px;
  border: 1px solid var(--border);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
  color: var(--text);
}

.subtitle {
  color: #6b6b6b;
  margin-bottom: 1.5rem;
  font-size: 0.95rem;
}

.servings-control {
  margin-bottom: 1.5rem;
}

.servings-control label {
  display: block;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.input-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.input-group button {
  width: 44px;
  height: 44px;
  font-size: 1.5rem;
  font-weight: 600;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--card-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.input-group button:hover {
  background: var(--bg);
  border-color: var(--accent);
}

.input-group button:active {
  transform: scale(0.95);
  background: var(--accent);
  color: white;
  border-color: var(--accent-dark);
}

.input-group button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.input-group input {
  width: 80px;
  height: 44px;
  font-size: 1.25rem;
  text-align: center;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--card-bg);
  color: var(--text);
  transition: border-color 0.15s;
}

.input-group input:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(61, 90, 128, 0.2);
}

.hint {
  display: block;
  font-size: 0.85rem;
  color: #6b6b6b;
  margin-top: 0.25rem;
}

.ingredient-list {
  list-style: none;
  border-top: 1px solid var(--border);
  padding-top: 1rem;
}

.ingredient-list li {
  display: flex;
  justify-content: space-between;
  padding: 0.6rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 1.1rem;
}

.ingredient-list li:last-child {
  border-bottom: none;
}

.ingredient-name {
  font-weight: 500;
}

.ingredient-amount {
  font-weight: 600;
  color: var(--accent-dark);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .input-group input {
    width: 60px;
  }
}

const recipe = [
  { name: "Flour", amount: 200, unit: "g" },
  { name: "Sugar", amount: 100, unit: "g" },
  { name: "Butter", amount: 80, unit: "g" },
  { name: "Eggs", amount: 2, unit: "" },
  { name: "Milk", amount: 150, unit: "ml" }
];

const BASE_SERVINGS = 4;
const servingsInput = document.getElementById('servings');
const decreaseBtn = document.getElementById('decrease');
const increaseBtn = document.getElementById('increase');
const ingredientList = document.getElementById('ingredient-list');

function roundToOneDecimal(value) {
  return Math.round(value * 10) / 10;
}

function renderIngredients(servings) {
  const factor = servings / BASE_SERVINGS;
  ingredientList.innerHTML = recipe.map(item => {
    const amount = roundToOneDecimal(item.amount * factor);
    return `<li><span class="ingredient-name">${item.name}</span><span class="ingredient-amount">${amount}${item.unit ? ' ' + item.unit : ''}</span></li>`;
  }).join('');
}

function clampServings(value) {
  const num = parseInt(value, 10);
  if (isNaN(num)) return BASE_SERVINGS;
  return Math.min(12, Math.max(1, num));
}

function updateServings(value) {
  const clamped = clampServings(value);
  servingsInput.value = clamped;
  renderIngredients(clamped);
}

servingsInput.addEventListener('input', (e) => {
  const val = e.target.value;
  if (val === '') return;
  updateServings(val);
});

servingsInput.addEventListener('blur', (e) => {
  updateServings(e.target.value);
});

decreaseBtn.addEventListener('click', () => {
  updateServings(parseInt(servingsInput.value, 10) - 1);
});

increaseBtn.addEventListener('click', () => {
  updateServings(parseInt(servingsInput.value, 10) + 1);
});

// Initial render
renderIngredients(BASE_SERVINGS);
